def task_func(url, table_id):
    if not url or not isinstance(url, str):
        raise ValueError("URL must be a non-empty string.")
    if not table_id or not isinstance(table_id, str):
        raise ValueError("Table ID must be a non-empty string.")

    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.HTTPError(f"HTTP request failed: {e}")

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', {'id': table_id})
    if table is None:
        raise ValueError("Table with the specified ID not found.")

    headers = [th.text.strip() for th in table.find_all('th')]
    rows = []
    for tr in table.find_all('tr'):
        cols = tr.find_all('td')
        if cols:
            rows.append([td.text.strip() for td in cols])

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows, columns=headers if headers else None)

