        url_legacy_compatible = url.startswith("http://localhost") or "dev." in url
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(url, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException:
        return []

    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
        dictionaries = []
        for script in scripts:
            try:
                content = script.string
                if content:
                    evaluated = ast.literal_eval(content)
                    if isinstance(evaluated, dict):
                        dictionaries.append(evaluated)
            except (ValueError, SyntaxError):
                continue
    except Exception:
        return []
    return dictionaries

