from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    if not isinstance(json_data, str) or not json_data:
        raise ValueError("Invalid JSON data provided.")
    try:
        data = json.loads(json_data)
        if unknown_key not in data or not isinstance(data[unknown_key], str):
            raise ValueError(f"Key '{unknown_key}' not found or invalid in JSON data.")
        url = data[unknown_key]
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except (json.JSONDecodeError, requests.RequestException) as e:
        raise ValueError(f"Error processing input or downloading file: {e}") from e

    timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"
    save_path = os.path.join(save_dir or os.getcwd(), filename)

    try:
        with open(save_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except OSError as e:
        raise ValueError(f"Error saving file: {e}") from e

    return os.path.abspath(save_path)

