import requests
def task_func(myString):
    url_pattern = r"https?://[^\s]+"
    match = re.search(url_pattern, myString)
    if not match:
        return "No valid URL found in the provided string."

    url = match.group(0)
    parsed_url = urlparse(url)
    if not parsed_url.scheme or not parsed_url.netloc:
        return "No valid URL found in the provided string."

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return f"Unable to fetch the content of the URL: {url}"

    soup = BeautifulSoup(response.text, 'html.parser')
    title_tag = soup.find('title')
    if not title_tag or not title_tag.text.strip():
        return "No title tag found in the webpage."

    return title_tag.text.strip()

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError(f"Invalid IP range provided: {e}")

    active_ips = []
    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue

    return active_ips

