# Constants
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL provided.")
    if not isinstance(parameters, dict):
        raise Exception("Parameters must be a dictionary.")

    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Error accessing the URL or retrieving data: {e}")

    if not data:
        raise Exception("Empty data received from the API.")

    try:
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty.")
        numerical_df = df.select_dtypes(include=['number'])
        if numerical_df.empty:
            raise Exception("No numerical data available for correlation analysis.")
        correlation_matrix = numerical_df.corr()
        ax = sns.heatmap(correlation_matrix, annot=True, cmap="coolwarm")
    except Exception as e:
        raise Exception(f"Error processing data: {e}")

    return df, ax

