from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    if not api_url or not isinstance(api_url, str):
        raise ValueError("Invalid API URL provided.")
    if not template_folder or not isinstance(template_folder, str):
        raise ValueError("Invalid template folder provided.")

    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPIResource(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json(), response.status_code
            except requests.RequestException as e:
                return {"error": str(e)}, 500

    api.add_resource(ExternalAPIResource, '/fetch-data')

    return app

